'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Stage, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './stage.css'

/**
 * Stage: Gamestage UI arranged around a scene the host owns.
 *
 * The scene is a Three.js canvas, a Unity build, a video, a static image or
 * somebody else's embed (BDS-032). `stage` never renders it, never reaches into
 * it, never measures it and never assumes it exists. It receives it as a node
 * and puts it on the page untouched.
 *
 * Three decisions carry the whole component.
 *
 * **The scene is in normal flow; everything else is absolute over it.** A stage
 * that set its own width or height would fight every host that embeds it, so it
 * sets neither. Instead the scene layer is an ordinary block, which means the
 * scene gives the stage its box, the way an `<img>` gives a figure its box. A
 * stage with no scene is exactly as tall as the host's container makes it, and
 * that is the host's business.
 *
 * **A layer is sized by what is in it unless it is meant to cover.** A `hud` or
 * a `nav` given a placement is pinned to that edge and is as big as its
 * contents; `behind`, `overlay`, `celebration`, anything with no placement and
 * anything placed `center` covers the stage. That distinction is what makes the
 * pointer rule expressible: a layer only takes presses over the area it
 * actually occupies, so a HUD in the corner does not swallow a tap meant for
 * the middle of the scene.
 *
 * **Presses fall through by default over the scene.** Every covering layer is
 * `data-gs-pointer-events="none"` unless the host says otherwise, and the scene layer
 * is always `auto`, because it is the host's and the library does not get to
 * decide how it is operated.
 */

/** The closed set from the attribute contract. A seventh would break the order. */
export type StageLayerName = 'scene' | 'behind' | 'hud' | 'overlay' | 'nav' | 'celebration'

export type StagePlacement =
  | 'top'
  | 'bottom'
  | 'left'
  | 'right'
  | 'center'
  | 'top-left'
  | 'top-right'
  | 'bottom-left'
  | 'bottom-right'

export interface StageLayerProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Which compositing layer this is. Decides the stacking order and nothing else. */
  layer: StageLayerName
  /** Where it sits in the stage. Ignored by layers that cover the whole stage. */
  placement?: StagePlacement
  /**
   * Whether presses land here or fall through to the scene. Defaults to `none`
   * for any layer that covers the stage and `auto` for one sized by its own
   * contents, which is the rule rather than a preference: a full-bleed layer
   * taking presses is the bug the attribute exists to make assertable. A layer
   * covers when it is `behind`, `overlay` or `celebration`, when it is given no
   * placement, or when it is placed `center`.
   */
  pointer?: 'none' | 'auto'
}

/** The layers that always cover the stage rather than sitting at an edge of it. */
const ALWAYS_COVERING: ReadonlySet<StageLayerName> = new Set(['behind', 'overlay', 'celebration'])

/**
 * Whether a layer covers the stage, which is what decides the pointer default.
 *
 * This is derived from the placement and not from the layer's name, and the
 * difference is a real bug rather than a nicety. A `hud` with no placement
 * keeps all four insets and covers the whole stage, and so does anything
 * placed `center`, which is the one placement that spans by design. Keying the
 * default on the name alone shipped a documented, supported configuration,
 * `<Stage.Layer layer="hud">` with no placement, that declared
 * `data-gs-pointer-events="auto"` across the entire scene and swallowed every press
 * meant for it.
 *
 * So there is one rule: a layer that covers takes no presses unless the host
 * insists, and a layer that is only as big as its contents may take them,
 * whatever it is called.
 */
function coversTheStage(layer: StageLayerName, placement?: StagePlacement) {
  if (layer === 'scene') return false
  if (ALWAYS_COVERING.has(layer)) return true
  return placement === undefined || placement === 'center'
}

/**
 * One layer of the stage. Exported on its own as well as reachable through
 * `Stage.Layer`, because a host composing layers in a loop needs the component
 * and not the property.
 */
export function StageLayer({
  layer,
  placement,
  pointer,
  className,
  children,
  ...rest
}: StageLayerProps) {
  // The scene is the host's, so the library never takes its presses away. A
  // layer that covers passes them through unless the host asks for them. An
  // edge-pinned one takes them, and can afford to, because it is only as large
  // as what is in it.
  const takesPresses = pointer ?? (coversTheStage(layer, placement) ? 'none' : 'auto')

  return (
    <div
      {...rest}
      className={['gs-stage__layer', className].filter(Boolean).join(' ')}
      data-gs-layer={layer}
      data-gs-placement={layer === 'scene' ? undefined : placement}
      data-gs-pointer-events={layer === 'scene' ? 'auto' : takesPresses}
    >
      {children}
    </div>
  )
}

export interface StageProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /**
   * The host's scene, rendered untouched into the scene layer. Any node: a
   * canvas, a video, an image, an iframe. The stage does not read it, size it
   * or style it, and omitting it is a supported case, because a quiz with no
   * scene uses the same components as a Unity build.
   */
  scene?: React.ReactNode
  /**
   * Where the library's layers sit relative to the scene. The host declares it;
   * the stage cannot infer it, because "over" and "around" render the same
   * layers and differ only in what the host meant.
   */
  arrangement?: 'over' | 'under' | 'around'
  /** The shape the layout is built around, when the host has one in mind. */
  format?: 'portrait' | 'landscape' | 'square'
  /**
   * Respect the device's safe areas. On by default: a stage is the component
   * most likely to be full-bleed on a phone, and a HUD under a notch is the
   * failure this prevents. A host that has already handled the insets itself
   * turns it off rather than paying them twice.
   */
  safeArea?: boolean
  /** The layers. `Stage.Layer` children, in any order; the CSS stacks them. */
  children?: React.ReactNode
}

export function Stage({
  scene,
  arrangement = 'over',
  format,
  safeArea = true,
  className,
  children,
  ...rest
}: StageProps) {
  return (
    <div
      {...rest}
      className={['gs-stage', className].filter(Boolean).join(' ')}
      data-gs-component="stage"
      data-gs-stage={arrangement}
      data-gs-format={format}
      data-gs-safe-area={safeArea ? 'true' : undefined}
    >
      {/*
        The scene goes first and in normal flow, so it gives the stage its box
        and every absolute layer resolves against it. Rendered only when the
        host passes one: an empty scene layer would be a zero-height block that
        contributes nothing and shows up in every selector counting layers.

        `{scene}` and nothing else. No wrapper inside, no ref, no measurement,
        no cloneElement: the moment the stage reads the scene it has an opinion
        about what a scene is, and the library's whole claim is that it does not.
      */}
      {scene !== undefined && scene !== null ? (
        <StageLayer layer="scene">{scene}</StageLayer>
      ) : null}
      {children}
    </div>
  )
}

Stage.Layer = StageLayer

/* Stage. Every value comes from a token; nothing here is a literal colour, and
   nothing here is a literal dimension either, because a stage that set its own
   dimensions would fight every host that embeds it.

   Two things this file deliberately does not do. It sets no width, no height
   and no aspect-ratio on the root: the scene in normal flow gives the stage its
   box, or the host's own container does. And it names no colour at all, not
   even a background, because the thing behind the layers is the host's scene
   and painting over it is the one failure the component exists to avoid. */

.gs-stage {
  /* The containing block every absolute layer resolves against. That is the
     only thing the root does. */
  position: relative;
  /* Layers are stacked by z-index, and z-index is only meaningful inside a
     stacking context the stage owns. Without this a host's own `z-index: 10`
     somewhere up the tree reorders the library's layers. */
  isolation: isolate;
}

/* The insets a phone takes away. Named once here rather than repeated in every
   layer rule, and zero when the host says it has handled them itself. `env()`
   is a browser value, not a design decision, which is why it is not a token. */
.gs-stage {
  --gs-stage-inset-top: 0px;
  --gs-stage-inset-bottom: 0px;
  --gs-stage-inset-left: 0px;
  --gs-stage-inset-right: 0px;
}

.gs-stage[data-gs-safe-area='true'] {
  --gs-stage-inset-top: env(safe-area-inset-top, 0px);
  --gs-stage-inset-bottom: env(safe-area-inset-bottom, 0px);
  --gs-stage-inset-left: env(safe-area-inset-left, 0px);
  --gs-stage-inset-right: env(safe-area-inset-right, 0px);
}

/* ------------------------------------------------------------ the scene -- */

/* In normal flow, so the host's scene gives the stage its box. Nothing about
   the scene is styled: no size, no background, no overflow, no transform. The
   layer exists to carry `data-gs-layer="scene"` and to sit at the bottom of the
   stack, and does not otherwise touch what is in it. */
.gs-stage__layer[data-gs-layer='scene'] {
  position: relative;
  z-index: 0;
}

/* ------------------------------------------------------ everything else -- */

/* Absolute, because the scene is the only thing in flow. Placement decides
   which edges are pinned; a layer with no placement covers the stage. */
.gs-stage__layer:not([data-gs-layer='scene']) {
  position: absolute;
  /* Inset by the device's own bite out of the screen, plus the library's own
     margin, so a HUD is never under a notch and never flush against the glass. */
  padding: var(--gs-space-4);
  top: var(--gs-stage-inset-top);
  right: var(--gs-stage-inset-right);
  bottom: var(--gs-stage-inset-bottom);
  left: var(--gs-stage-inset-left);
}

/* The stacking order is the library's, which is why `data-gs-layer` is a closed
   set. Behind the scene, then the scene, then the readouts, then whatever is
   asking to be read, then navigation, then celebration over everything. No
   token names these; the request is in the contract. */
.gs-stage__layer[data-gs-layer='behind']      { z-index: -1; }
.gs-stage__layer[data-gs-layer='hud']         { z-index: 1; }
.gs-stage__layer[data-gs-layer='overlay']     { z-index: 2; }
.gs-stage__layer[data-gs-layer='nav']         { z-index: 3; }
.gs-stage__layer[data-gs-layer='celebration'] { z-index: 4; }

/* A layer that sits at an edge is as big as what is in it, which is what makes
   `data-gs-pointer-events="auto"` safe on it: it can only swallow a press inside its
   own contents. Each placement releases the edges it is not pinned to. */
.gs-stage__layer[data-gs-placement='top']    { bottom: auto; }
.gs-stage__layer[data-gs-placement='bottom'] { top: auto; }
.gs-stage__layer[data-gs-placement='left']   { right: auto; }
.gs-stage__layer[data-gs-placement='right']  { left: auto; }

.gs-stage__layer[data-gs-placement='top-left']     { bottom: auto; right: auto; }
.gs-stage__layer[data-gs-placement='top-right']    { bottom: auto; left: auto; }
.gs-stage__layer[data-gs-placement='bottom-left']  { top: auto; right: auto; }
.gs-stage__layer[data-gs-placement='bottom-right'] { top: auto; left: auto; }

/* Centre is the one placement that covers the stage and still has to lay its
   contents out, so it keeps all four edges and centres what is in it. */
.gs-stage__layer[data-gs-placement='center'] {
  display: grid;
  place-items: center;
}

/* ---------------------------------------------------------- the presses -- */

/* The pointer rule, as two lines. `data-gs-pointer-events` is what the component
   declares and this is the only place it becomes behaviour, so a browser test
   asserting the attribute is asserting the thing that is true. */
.gs-stage__layer[data-gs-pointer-events='none'] { pointer-events: none; }
.gs-stage__layer[data-gs-pointer-events='auto'] { pointer-events: auto; }

/* A covering layer passes presses through, and a control a host puts inside one
   anyway has to be reachable: an overlay with a Skip button is the case. The
   layer stays transparent and its direct children do not, which is the standard
   way round and the reason `data-gs-pointer-events` has two values rather than three.

   The obligation this puts on the host is real and is documented with the
   component: a direct child of a covering layer takes presses across whatever
   area it occupies, so a child stretched to `height: 100%` re-swallows the
   whole scene while the layer's attribute still reads `none`. Size the child to
   its content. A test asserting the attribute would pass over that, which is
   the gate describing what got built rather than what was meant. */
.gs-stage__layer[data-gs-pointer-events='none'] > * { pointer-events: auto; }

/* --------------------------------------------------------- composition -- */

/* There is no rule here for `hud`, for `nav` or for anything else the host puts
   in a layer, and that is the result worth recording rather than an omission.
   A layer is a block box with its edges pinned, so whatever goes in it lays
   itself out exactly as it does anywhere else and needs nothing from this file.
   The moment stage styled another component's class it would be writing a rule
   whose winner depends on which stylesheet the bundler put last: stage depends
   on no component, so it has no import-order claim on any of them. */
